# --- Configuration ---
# NOTE: The server is running on port 8083 locally.
UPLOAD_URL = "http://127.0.0.1:8083/upload"
DOWNLOAD_URL_BASE = "http://127.0.0.1:8083/download"

# ⚠️ ACTION REQUIRED: REPLACE WITH A REAL, VALID JWT
# This token MUST be the one generated by your Auth Service. 
